INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1198558-chem202', 'stk-chemist', 'CHEM 202', 'info', '{"desc": "أخ الله يأخذ الأبت يوم حذفوا هذي المادة الممتعة جدا\nالكتاب المستخدم لهذي المادة هو نفسه الكتاب ل 201 ومنهج 202 أسهل من 201\nيغطي منهج 202 الحموض الكربوكسيلية والكيتونات والألدهايدات والإيسترات والبنزن وتفاعلاته والكيربوهيدرات والأحماض الأمينية و السبكتروقرافيه\n\nعيب المادة انها طويله شويتين\n\nالاب\nأفضل لاب في الجامعة مرعلي أكثره مبني على Crystillation And Extraction to determine the Organic compound ماتطول ساعتين بالكثير وانت ماشي 👍\n\nبوجهة نظري اشوف ان مايدرس في CHEM 202 يستفيد منه المهندس الكيميائي بشكل كبير في عمليات صناعة المواد البيتروكيمائية والبوليمرات والمواد الصيدله وغيرها", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/chem-202-organic-chemistry-ii/120593/2", "user": "Chemist", "ts": 1363046116000, "tid": 120593, "pn": 2}}', 1363046116000, 1794826848, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p594424-chem202', 'stk-user4459', 'CHEM 202', 'info', '{"desc": "يا ناس والله الكتاب أفضل شي\n\nأنا جربت السلايدات وقارنتها بالكتاب شفت الكتاب أفضل بكثير\n\nمميزات الكتاب انه :\n\nمنظم\n\nو واضح و كامل و سهل الفهموالسلايدات هي نفس الي في الكتاب مع انها ما هي كامله , بس يفضل تمر عليها اذا خلصت من الكتاب\n\nولا تنسون الاسئله الي في اخر الشابتر\n\n🌹", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/chem-202/84425/11", "user": "user4459", "ts": 1272241843000, "tid": 84425, "pn": 11}}', 1272241843000, 1794826848, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user1548-chem202', 'stk-user1548', 'CHEM 202', 'doc', '{"docs": [{"id": "stk-dr-f68450", "n": "د. بسام علام الدين", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "انا عنده حاليا في chem 202\n\nالتحضير : يومي وبالأسماء ، (شديد)\nطريقة الشرح : سلايدات + السبورة\nالكويزات : أصعب من المياجر\nالمياجر: كومون بين دكتوري المادة (2 دكتور)\nالفاينلات : ----لسه ما وصلت---\nالقريد النهائي: ----لسه ما وصلت---\nالصوت: واضح جداً ، ويحب أن يستخدم اللغة الانجليزية لكامل الكلاس\nإضافات : ---", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p345081-chem202", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/68450/3", "user": "user1548", "ts": 1230559782000, "tid": 68450, "pn": 3}}]}', 1230559782000, 1794826848, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-chemist-chem202', 'stk-chemist', 'CHEM 202', 'doc', '{"docs": [{"id": "stk-dr-f68454", "n": "د. عبدالله الحمدان", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Chem 202 Term 102\n\nالتحضير : بداية كل كلاس\n\nالشرح:\nكان يشرح بسلايدات وكان شرحه ممتاز يعطيك الزبدة ويعودك على التركات اللي تجي في المياجر وماشاء الله عليه متمكن من الماده وفي بعض الاحيان يعطينا مسألة في الفصل من ضمن الدرس كتحدي وتدريب لنا وهذا الشئ افادني واعجبني صراحة\n\nالكوزات:\nتقريبا طبق الأصل للكويزات القديمة الموجودة في موقعه الشخصي ومتوسطة المستوى\n\nاضافات:\nتعامله مع الطلاب اكثر من رائع يعاملهم وكأنه اخوهم الكبير وحصة مفيدة جدا وممتعه\n\nالقريد النهائي:\nA", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1044063-chem202", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/68454/16", "user": "Chemist", "ts": 1337900971000, "tid": 68454, "pn": 16}}]}', 1337900971000, 1794826848, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-saleh_h-chem202', 'stk-saleh_h', 'CHEM 202', 'doc', '{"docs": [{"id": "stk-dr-f68460", "n": "Dr. Nisar Ullah", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "CHEM202(CHEM201 LAB) - Term211\n\nالتحضير : يحضر عن طريق الريبورت ويمشي التأخير.\nطريقة الشرح : شرحه ممتاز جدا يعلمك النظرية من اللكتشر وبالنسبة لي دروس ماكنت افهمها من دكتور اللكتشر افهمها من ذا الدكتور، ويشرح لك التجربة ويعطيك الزبدة بحيث انك تعرف وش المفروض تسويه.\nالكويزات : سهلة الى متوسطة، يجيبها من الشرح على السبورة وكان يخلينا نصورها عشان نذاكر للكويزات.\nالمياجر: كومن\nالفاينلات : كومن\nالقريد النهائي: ِA+++\nالصوت: واضح جدا وعلى انه باكستاني لكن ما شاء الله الاكسنت حقه واااضح جدا لدرجة ما تحس انه باكستاني :).\nإضافات : الدكتور حبييييب جدا وقمة بالاخلاق والتعامل وكان يعاملنا كأننا عياله، واذا فيه شي مافهمته بالتجربة يجي ويشرح لك ويساعدك بالتجربة ولا تستغرب لو سواها عنك بعد، + تصحيحه جدا رهيب ويعطيك فوق حقك ومحد ينزل عن 85% بالاضافة ان الدكتور يمقت ان الطالب يمسك جواله بالشرح ويزعل وبيغسل شراعك لو صارت بالاضافة ان ما يطيق اي طالب ما ينظف وراه ويخسف درجة الريبورت لو واحد ما نظف وراه، انا سكشني كانو نظيفين لدرجة ان بعض الاشياء اللي مفروض نخليها ننظفها والدكتور استانس وحذف لنا أسوأ كويز،عموما لو حصلت لك فرصة لا تفوته ابدا لانه هو الافضل بلا منازع.\n\nموفقين إن شاء الله…", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1533461-chem202", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/nisar-ullah/68460/33", "user": "Saleh_H", "ts": 1642159096000, "tid": 68460, "pn": 33}}]}', 1642159096000, 1794826848, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user9305-chem202', 'stk-user9305', 'CHEM 202', 'doc', '{"docs": [{"id": "stk-dr-f68482", "n": "Dr. Shaikh Ali", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "CHEM 202 (Organic Chemistry II) - Term 142 Lec & Lab\n\nالتحضير:\nورقة تمر يومياً وما ينسى أبداً.\n\nطريقة الشرح:\nيكتب الدرس كامل في سبورة واحدة بدون ما يمسح ويكتب باستخدام طباشير ملونة وبترتيب بديع.\n\nالكويزات:\nكلهن كانن Take home ومستواهن مرتفع، أذكر كنت أقعد 5-6 ساعات على كويز واحد خاصة في مادة ميجر 1.\n\nالمياجر:\n- ميجر 1 كان كتابي وصعب لأن أصلاً مادته ليست بالبسيطة واللي هي NMR & IR & UV graph interpretation.\n- ميجر 2 كان كتابي ومتوسط المستوى، وصراحة الأسئلة حقته ممتعة وتحس بمتعة غريبة وانت تقرأ السؤال المكتوب بعناية من قبل دكتور متبحر مثل شيخ علي.\n\nالفاينل:\nكان متوسط لكن يحوي 60 سؤال اختيارات.\n\nالصوت:\nواضح جداً.\n\nإضافات:\n- الدكتور في المحاضرة ما يتفوت أبداً وتحس انك أمام بحر لا ساحل له في الكيمياء العضوية ما شاء الله تبارك الله لكن في المختبر شرس نوعاً ما ويعنف الطلاب بشدة خاصة لو نبه على ترك شيء ثم وجد طالب يفعله. وفي الأخير إذا شاف الطالب شالها في نفسه يجي يعتذر منه ويكرر الإعتذار حتى يرضيه.\n\n- يحب الطلاب يزورونه في مكتبه رغم انشغاله الشديد بأبحاثه وطلاب الماستر والدكتوراه عنده، يداوم من 7 وحتى صلاة العشاء.\n\n- كانت محاضرتي الساعه 7 وكان يكره المتأخرين فوق 5 دقايق ويلوم الغائبين دائمأً، ممكن لأننا كنا 6 طلاب فغياب واحد يؤثر على البقية لكن هذي نقطة تؤخذ بالحسبان.\n\n- إذا درست معه فيحق لك تكتب هذا في السيرة الذاتية خاصتك، فشيخ علي علم في رأسه نار.\n\nالقريد النهائي:\nA+ وقليلة في حقه.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1444388-chem202", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/shaikh-ali/68482/15", "user": "user9305", "ts": 1458341167000, "tid": 68482, "pn": 15}}]}', 1458341167000, 1794826848, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user12136-chem202', 'stk-user12136', 'CHEM 202', 'doc', '{"docs": [{"id": "stk-dr-f68482", "n": "Dr. Shaikh Ali", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "chem202 term 211\n\nالتحضير : يحضر بالريبورت والكوزات وعموما متساهل في التأخير مدة 5 دقائق\nطريقة الشرح : جداً جداً واضحة وممتازة، يشرح التجربة حبة حبة ونسوي اللاب مع بعض بدون فوضى والكل متابع معاه، اللاب معاه سلس ومريح واسلوبه في الشرح يضحك والله ويلطف الجو\nالكويزات : سهلة جدا بس لازم تكون مركز، وهو ما يحب يكثر من الكوزات\nالفاينلات : كومن واذكر انه سوه لنا مراجعة سريعة قبل الفاينل\nالقريد النهائي: A+++++\nالصوت: واضح\nإضافات :\nاسمع كلامي زين وبتشكرني بعدين… اكتب الريبورت بشكل مرتب وبخط حلو وبانقليزي مضبوط وأهم شي عنده الترتييييب، لا تشخبط كثير، للاسف منحاز هو للريبورتات الي تكتب بخط جميل، بس عموما ما ينقص وايد", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1533412-chem202", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/shaikh-ali/68482/17", "user": "user12136", "ts": 1641983079000, "tid": 68482, "pn": 17}}]}', 1641983079000, 1794826848, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-che28-chem202', 'stk-che28', 'CHEM 202', 'doc', '{"docs": [{"id": "stk-dr-f81012", "n": "Dr. Mohammad Al-Imam", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "هذا انا ادرس عنده ترم 102\nchem202\nما انصح به ابدا …\nما يكتب البروسيجر ويقولك انت اقرأها وعلم نفسك بنفسك الا ماندر مرتين او ثلاث هو كتب البروسيجر\nودائما يطلب الميكانيسم حق التجربة ومعظم الأحيان المكانيسم مو موجود في كتاب الاب وتكون المكانيسم من فهمك للكشر واذا كان مدرس اللكشر متأخر في الماتيرال فبتروح عليك\nواذا خلصنا من وقت … يطلب مننا نحل كم سؤال من اسئلة التجربة\nواحسن شيء انه ما يعطي كويز ولاكن اسئلة التجارب والميكانيسم بتكون اعظم من الكويزات\n\nطبعا هو غير اسلوبه عن تيرم 101 … وها نحن ولست انا … نعاني معه في تيرم 102 في الاب", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p840417-chem202", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mohammad-al-imam/81012/19", "user": "che28", "ts": 1304440754000, "tid": 81012, "pn": 19}}]}', 1304440754000, 1794826848, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user3354-chem202', 'stk-user3354', 'CHEM 202', 'doc', '{"docs": [{"id": "stk-dr-f90836", "n": "د. عامر عدنان البطة", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "اخذت عنده لاب chem 202 سمستر 092\n\nالتحضير : بداية اللاب ينادي الاسماء …\n\nطريقة الشرح : بداية يوزع المانيول حق تجربة اليوم ويبدا يشرح التجربة … شرحه بطل والله يوصل\n\nالمعلومة ومايطول بالشرح… ركز كثير بـالـ*structures تبع المركبات لانه يجيب منهم اسئلة بالكوزات\n\nالكويزات : سهله وركز ديام على المانيوالز تبع التجارب يجيب منهم وكذلك الاشياء المهمه باللاب الماضي\n\nدايم يقولك اذا فيه كوز اللاب الجاي\n\nالمياجر: كومون\n\nالفاينلات : كومون\n\nالقريد النهائي: اعطيه A\n\nالصوت: واضح جدا وعلى فكرة الدكتور هذا اردني الاصل امريكي الجنسية يعني الاكسنت اوكيي\n\nإضافات : الدكتور اخلااااق عاليه وشرحه رهييييب كان احيانا اذا فيه شي مو فاهمينه من اللكتشر\n\nيشرحه لنا باللب صراحه قممممة ما شاء الله عليه\n\nبالقريد يعطي الطلاب تقريبا كلهم بنفس الرينج بحدود 17-19 شد حيلك معاه بالريبورت واتبع الفورمات\n\nحقه لانه عنده فورمات يعطيك بداية السمستر يبيك تسوي الريبورت زيها اتبعها بالضبط\n\nمايطول باللاب يعني حدود ساعه ونص او ساعتين بالكثير وانت خارج …\n\nيساعد دايم بالتجارب اللي مو فاهم واحيانا يشتغل بيده مع الطلاب …\n\nصراحه من افضل واحد ممكن تنزل معاه لاب بالاورقانك…", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p693858-chem202", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/90836/4", "user": "user3354", "ts": 1283156087000, "tid": 90836, "pn": 4}}]}', 1283156087000, 1794826848, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
